// Sound-masking index — record JAH-GGN-WHITENOISE-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"sounds": 10, "battery_h": 999, "price_usd": 50};
var value = (m.sounds*m.battery_h/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GGN-WHITENOISE-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GGN-WHITENOISE-000001|' + value.toFixed(2) + ' masking index');

